            crate::packslip::fetch_files(&tv, &statement, Some(&artifact), ctx.pr.as_ref()).await?;
        }
        Ok((
            tv,
            PendingPin {
                project,
                scheme: observed.scheme.to_owned(),
                key_id: observed.key_id.to_owned(),
                issuer: observed.issuer.map(str::to_owned),
                attested_by: observed.attested_by.to_owned(),
                provenance: observed.provenance,
                        .lock()?;
                    let original_content = read_optional_file(&lockfile_path)?;
                    let mut lockfile = Lockfile::read(&lockfile_path)?;
                    if self.json {
                        all_changes.extend(self.compute_version_changes(
                            &lockfile,
                            &tools,
                            &lockfile_path,
                        ));
                    }
                    let pruned_tools = self.prune_stale_entries_if_needed(
                        &mut lockfile,
                        configured_selectors.as_ref(),
                    );
                    let format_changed = if self.upgrade {
