assert_contains "MISE_OFFLINE=1 mise --locked exec hk@1.57.0 -- hk --version" "hk 1.57.0"
assert_contains "MISE_OFFLINE=1 mise --locked exec hk@1.58.1 -- hk --version" "hk 1.58.1"
assert_fail_contains "MISE_DISABLE_BACKENDS=aqua mise latest hk@1.57" "none of its backends"

# Aliases can cross the boundary after their version string is resolved.
cat >>mise.toml <<'TOML'
[tool_alias.hk.versions]
old = "1.57.0"
old_prefix = "prefix:1.57"
TOML
assert_contains "mise exec hk@old -- hk --version" "hk 1.57.0"
assert "mise latest hk@old" "1.57.0"
assert_contains "mise ls-remote hk@old" "1.57.0"
assert_contains "mise ls-remote hk@old_prefix" "1.57.0"

# Explicit backends remain explicit; no fallback after a verification error.
assert_fail_contains "mise install --force packslip:github.com/jdx/hk@1.57.0" "no release"

item.aggregated_output:
        &self,
        ctx: &InstallContext,
        mut tv: ToolVersion,
        vfox_plugin: bool,
    ) -> Result<(ToolVersion, PendingPin)> {
        let project = self.project()?;
        let raw_opts = tv.request.options();
        let opts = PackslipOptions::new(&raw_opts);
        let pin = pin(&project, &opts)?;
        let require_log = !opts.allow_unlogged();

        // A stamp first, when the settings ask for one: it says this exact
        // manifest is admitted, and points at it. Then the manifest: nothing
        // else is downloaded until it verifies.
        let stamp = match crate::packslip_stamps::fetch(&project, &raw_opts).await? {
            Some(stamps) => Some(
                stamps
                    .stamp(&tv.version)
                    .ok_or_else(|| stamps.refusal(&project, &tv.version))?
                    .clone(),
            ),
            None => None,
        };
        // The vendor stays authoritative for withdrawals and digest pins even
        // when a stamper supplies a mirror URL. What the vendor's list cannot
        // speak to is whether the original release asset is still on GitHub,
        // and a stamp already names the manifest and its digest — so mise asks
        // the signed list here rather than `locate_bundle`, and a deleted asset
        // does not veto a release the vendor never withdrew.
        let (located, vendor_digest) = match &stamp {
            Some(stamp) => {
                debug!(
                    "{}: stamped by {}, manifest at {}",
                    tv.style(),
                    stamp.host,
                    stamp.entry.packslip
                );
                // A stamp says a host reviewed this manifest, and the digest is
                // the whole of what ties the claim to a file. Without one the
                // stamp admits a URL, and any later manifest the vendor signs
                // for this version can stand at it in place of the reviewed
                // one — so refuse rather than call that a review.
                let Some(digest) = stamp.digest.clone() else {
                    bail!(
                        "the stamp for packslip:{project}@{} from {} records no sha256 for {}, so nothing says the manifest is the one that host reviewed",
                        tv.version,
                        stamp.host,
                        stamp.entry.packslip
                    );
                };
                let vendor = self.vendor_entry(&project, &tv, &pin, &opts).await?;
                (
                    Located {
                        headers: headers_for(&stamp.entry.packslip)?,
                        url: stamp.entry.packslip.clone(),
                        digest: Some(digest),
                    },
                    vendor.and_then(|v| v.digest),
                )
            }
            // Without a stamp the located bundle is the vendor's own, so its
            // digest is already the one checked below.
            None => (self.locate_bundle(&project, &tv, &pin, &opts).await?, None),
        };
        let bundle_path = tv.download_path().join(bundle_name(&project));
        file::create_dir_all(tv.download_path())?;
        ctx.pr.set_message("download packslip".into());
        HTTP.download_file_with_headers(
            &located.url,
            &bundle_path,
            &located.headers,
            Some(ctx.pr.as_ref()),
        )
        .await?;
        let pinned: Vec<&String> = located.digest.iter().chain(vendor_digest.iter()).collect();
        if !pinned.is_empty() {
            let (actual, _) = packslip::digest_file(&bundle_path)?;
            for expected in pinned {
                if &actual != expected {
                    bail!(
                        "the packslip at {} is not the one the signed release list points at (sha256 {actual}, list says {expected})",
                        located.url
                    );
                }
            }
        }
        let bundle = file::read_to_string(&bundle_path)?;
        ctx.pr.set_message("verify packslip".into());
        let verified = verify_bundle(&bundle, &pin, require_log, &[])
            .wrap_err_with(|| format!("verifying the packslip of {}", tv.style()))?;
        let payload = packslip::sigstore::peek_statement(&bundle).map_err(|e| eyre!("{e}"))?;
        let statement: Statement = serde_json::from_slice(&payload)?;
        if verified.project != project {
            bail!("the packslip is for {}, not {project}", verified.project);
        }
        if verified.version != tv.version {
            bail!(
                "the packslip says version {}, not {}; the release's tag and its manifest disagree",
                verified.version,
                tv.version
            );
        }
        debug!(
            "{}: packslip signed by {} ({}){}",
            tv.style(),
            verified.key_id,
            verified.scheme,
            verified
                .logged_at
                .as_deref()
                .map(|t| format!(", logged {t}"))
                .unwrap_or_default()
        );
        let before = crate::install_before::resolve_before_date_for_tool(
            &self.ba,
            tv.before_date.or(ctx.before_date),
            raw_opts.minimum_release_age(),
        )?;
        check_verified_age(
            verified.logged_at.as_deref(),
            &verified.published_at,
            before,
        )?;

        // Who signed, against what this machine accepted before, and then
        // against what the project committed to in its lockfile.
        let scheme = verified.scheme.to_string();
        let attested_by = verified.attested_by.to_string();
        // Nothing is recorded until the release is accepted in full, so a
        // refused install leaves no pin behind.
        let observed = Observed {
            scheme: &scheme,
            key_id: &verified.key_id,
            issuer: verified.issuer.as_deref(),
            attested_by: &attested_by,
            provenance: verified.provenance_linked,
            logged: verified.logged_at.is_some(),
        };
        packslip_pins::check(&project, observed)?;
        let signer = format!(
            "{scheme}:{}",
            packslip_pins::signer_of(&scheme, &verified.key_id)
        );
        let platform_key = self.get_platform_key();
        // The signer describes the release, so every platform's lock entry
        // speaks for it, not only this host's.
        for info in tv.lock_platforms.values() {
            if let Some(locked) = &info.signer
                && *locked != signer
            {
                bail!(
                    "mise.lock says {} signed {}, but this release is signed by {signer}; remove the entry from mise.lock to accept the new signer",
                    locked,
                    tv.style()
                );
            }
            if info.attested_by.is_none()
                && info.signer.is_some()
                && verified.attested_by == packslip::Attestor::Repackager
            {
                bail!(
                    "mise.lock says the vendor's own packslip was accepted for {}, but this release is a repackager's; remove the entry from mise.lock to accept that",
                    tv.style()
                );
            }
        }

        // Then the one artifact for this host, by what the manifest says.
        let artifact = select_artifact(
            &statement.predicate.artifacts,
            &HostPlatform::current(),
            opts.variant().as_deref(),
        )?
        .clone();
        if vfox_plugin {
            crate::plugins::packslip::validate_artifact(&artifact)?;
        }
        let mut commands = BTreeMap::new();
        if let Some(req) = &artifact.requires {
            for bin in &req.bin {
                // Spawnable, not merely present: the probe below runs the
                // path with `--version`, so a shebang-only script or a `.ps1`
                // would be chosen and then fail to start.
                if let Some(path) = ctx.ts.which_bin_spawnable(&ctx.config, &bin.name).await {
                    commands.insert(bin.name.clone(), path);
                }
            }
        }
        crate::packslip_requirements::check(&artifact, &commands)
            .await
            .enforce(raw_opts.get("ignore_requirements") == Some("true"))?;
        let Some(url) = artifact.url.clone() else {
            bail!("the packslip gives no download URL for {}", artifact.name);
        };
        if !file::is_plain_file_name(&artifact.name) {
            bail!(
                "the packslip names an artifact {:?}, which is not a plain file name",
                artifact.name
            );
        }
        let file_path = tv.download_path().join(&artifact.name);
        ctx.pr.next_operation();
        ctx.pr.set_message(format!("download {}", artifact.name));
        HTTP.download_file_with_headers(
            &url,
            &file_path,
            &headers_for(&url)?,
            Some(ctx.pr.as_ref()),
        )
        .await?;

        // The signed digest and size first, then what the lockfile remembers:
        // a lock entry written from an earlier packslip keeps its checksum and
        // is compared, so a newly signed manifest cannot quietly replace what
        // the project committed to. A fresh entry records the signed sha256.
        ctx.pr.next_operation();
        ctx.pr.set_message(format!("verify {}", artifact.name));
        verify_bundle(&bundle, &pin, require_log, &[&file_path])
            .wrap_err_with(|| format!("verifying {} against its packslip", artifact.name))?;
        {
            let info = tv.lock_platforms.entry(platform_key).or_default();
            info.url = Some(url);
            if info.checksum.is_none()
                && let Some(sha256) = statement.digest_of(&artifact.name)
            {
                info.checksum = Some(format!("sha256:{sha256}"));
            }
            info.signer = Some(signer);
            // Set for a repackager's document and cleared for the vendor's,
            // so the lockfile ratchets up the way the pin does.
            info.attested_by = (verified.attested_by == packslip::Attestor::Repackager)
                .then(|| "repackager".to_string());
        }
        self.verify_checksum(ctx, &mut tv, &file_path)?;

        // Unpack as the manifest describes the file, not as its name suggests.
        ctx.pr.next_operation();
        let mut install_opts = tv.request.options();
        if let Some(format) = &artifact.format {
            install_opts
                .insert_option("format".into(), toml::Value::String(format.clone()))
                .map_err(|e| eyre!(e))?;
        }
        // A bare executable, compressed or not, lands at the path its bin
        // entry names: the artifact's own name minus any compression suffix.
        if artifact.format.as_deref().is_some_and(is_bare_format)
            && let Some(bin) = artifact.bin.first()
        {
            install_opts
                .insert_option("bin".into(), toml::Value::String(bin.path.clone()))
                .map_err(|e| eyre!(e))?;
        }
        // The statement names every executable by path, so nothing here may
        // rename one: a tidied platform suffix would put the file somewhere the
        // statement does not point, and `link_bins` would not find it.
        if vfox_plugin {
            crate::plugins::packslip::validate_archive(&file_path)?;
        }
        install_artifact(
            &tv,
            &file_path,
            &install_opts,
            ArchiveLayout::Declared,
            Some(ctx.pr.as_ref()),
        )?;
        if vfox_plugin {
            crate::plugins::packslip::validate_layout(&tv.install_path())?;
        }
        Self::link_bins(&tv, &artifact)?;
        file::write(
            tv.install_path().join(STATEMENT_FILE),
            serde_json::to_vec_pretty(&statement)?,
        )?;
        // Completions and CLI specs the vendor keeps outside the artifact.
        if !vfox_plugin {
            crate::packslip::fetch_files(&tv, &statement, Some(&artifact), ctx.pr.as_ref()).await?;
        }
        Ok((
            tv,
            PendingPin {
                project,
                scheme: observed.scheme.to_owned(),
                key_id: observed.key_id.to_owned(),
                issuer: observed.issuer.map(str::to_owned),
                attested_by: observed.attested_by.to_owned(),
                provenance: observed.provenance,
                        .lock()?;
                    let original_content = read_optional_file(&lockfile_path)?;
                    let mut lockfile = Lockfile::read(&lockfile_path)?;
                    if self.json {
                        all_changes.extend(self.compute_version_changes(
                            &lockfile,
                            &tools,
                            &lockfile_path,
                        ));
                    }
                    let pruned_tools = self.prune_stale_entries_if_needed(
                        &mut lockfile,
                        configured_selectors.as_ref(),
                    );
                    let format_changed = if self.upgrade {
                        if lockfile.tools().is_empty() {
                            self.prepare_lockfile_format(&lockfile_path, &mut lockfile)
                        } else {
                            bail!(
                                "cannot upgrade {} because no configured tools were resolved",
                                display_path(&lockfile_path)
                            );
                        }
                    } else {
                        self.report_lockfile_format(&lockfile_path, &lockfile, false)?;
                        false
                    };
                    if format_changed || !pruned_tools.is_empty() {
                        if self.upgrade {
                            staged_upgrade_writes.push(StagedUpgradeWrite {
                                path: lockfile_path.clone(),
                                original_content,
                                lockfile,
                                summary: None,
                                format_changed,
                                stale_tools: pruned_tools.clone(),
                                stale_versions: BTreeMap::new(),
                            });
                        } else {
                            lockfile.write(&lockfile_path)?;
                        }
                        if !self.upgrade {
                            self.show_stale_prune_message(&lockfile_path, &pruned_tools, false)?;
                        }
                        has_lock_targets = true;
                    }
                }
                continue;
            }
            has_lock_targets = true;

            let target_platforms = self.determine_target_platforms(&lockfile_path)?;

            if !self.json {
                miseprintln!(
                    "{} Targeting {} platform(s) for {}: {}",
                    style("→").cyan(),
                    target_platforms.len(),
                    style(display_path(&lockfile_path)).cyan(),
                    target_platforms
                        .iter()
                        .map(|p| p.to_key())
                        .collect::<Vec<_>>()
                        .join(", ")
                );

                miseprintln!(
                    "{} Processing {} tool(s): {}",
                    style("→").cyan(),
                    tools.len(),
                    tools
                        .iter()
                        .map(|(ba, tv)| format!("{}@{}", ba.short, tv.version))
                        .collect::<Vec<_>>()
                        .join(", ")
                );
            }

            if self.dry_run {
                self.show_dry_run(&tools, &target_platforms)?;
                let lockfile = Lockfile::read(&lockfile_path)?;
                self.report_lockfile_format(&lockfile_path, &lockfile, true)?;
                if self.json {
                    all_changes.extend(self.compute_version_changes(
                        &lockfile,
                        &tools,
                        &lockfile_path,
                    ));
                }
                if self.is_unfiltered_lock_run() {
                    let stale_tools =
                        self.stale_entries_if_pruned(&lockfile, configured_selectors.as_ref());
                    self.show_stale_prune_message(&lockfile_path, &stale_tools, true)?;
                }
                let stale_versions = self.stale_versions_if_pruned(&lockfile, &tools);
                self.show_stale_version_prune_message(&lockfile_path, &stale_versions, true)?;
                continue;
            }

            // Process tools and update lockfile
            let _lock = crate::lock_file::LockFile::new(&lockfile_path)
                .with_callback(|l| debug!("waiting for lock on {}", display_path(l)))
                .lock()?;
            let original_content = read_optional_file(&lockfile_path)?;
            let mut lockfile = Lockfile::read(&lockfile_path)?;
            if !self.upgrade {
                self.report_lockfile_format(&lockfile_path, &lockfile, false)?;
            }
            if self.json {
                all_changes.extend(self.compute_version_changes(&lockfile, &tools, &lockfile_path));
            }
            let stale_tools =
                self.prune_stale_entries_if_needed(&mut lockfile, configured_selectors.as_ref());
            if !self.upgrade {
                self.show_stale_prune_message(&lockfile_path, &stale_tools, false)?;
            }

            // Compute stale versions BEFORE process_tools so provenance checks can
            // compare against old version entries. Actual pruning happens after.
            let stale_versions = self.stale_versions_if_pruned(&lockfile, &tools);

            let (results, resolution_errors) = self
                .process_tools(&settings, &tools, &target_platforms, &mut lockfile)
                .await?;
            let resolution_succeeded = resolution_errors.is_empty();
            all_resolution_errors.extend(resolution_errors);

            let platform_regressions =
                self.platform_regression_errors(&lockfile, &stale_versions, &results);
            if !platform_regressions.is_empty() {
                all_platform_regressions.extend(platform_regressions);
                continue;
            }

            let format_changed =
                self.upgrade && lockfile.lockfile_version() == 0 && resolution_succeeded;
            if format_changed {
                self.prepare_lockfile_format(&lockfile_path, &mut lockfile);
                if !self.bind_requests(&mut lockfile, &tools, &target_platforms) {
                    bail!(
                        "cannot upgrade {} because not every request binding was resolved",
                        display_path(&lockfile_path)
                    );
                }
            } else {
                self.bind_requests(&mut lockfile, &tools, &target_platforms);
            }

            // Prune stale versions AFTER provenance checks complete
            self.prune_stale_versions(&mut lockfile, &tools);
            if !self.upgrade {
                self.show_stale_version_prune_message(&lockfile_path, &stale_versions, false)?;
            }

            let successful = results
                .iter()
                .filter(|result| matches!(result.status, LockTaskStatus::Updated))
                .count();
            let skipped = results.len() - successful;
            if self.upgrade {
                staged_upgrade_writes.push(StagedUpgradeWrite {
                    path: lockfile_path.clone(),
                    original_content,
                    lockfile,
                    summary: Some((successful, skipped)),
                    format_changed,
                    stale_tools,
                    stale_versions,
                });
            } else {
                // Normal lock runs preserve successful updates even if another
                // target reports a non-regressing resolution error.
                lockfile.write(&lockfile_path)?;
            }

            // Print summaries for normal writes now. Upgrade summaries are
            // deferred with their writes until every target succeeds.
            if !self.json && !self.upgrade {
                miseprintln!(
                    "{} Updated {} platform entries ({} skipped)",
                    style("✓").green(),
                    successful,
                    skipped
                );
                miseprintln!(
                    "{} Lockfile written to {}",
                    style("✓").green(),
                    style(display_path(&lockfile_path)).cyan()
                );
            }
        }

        if !has_lock_targets && !self.json {
            // --local asks for mise.local.lock specifically, and there is no global
            // equivalent, so don't redirect that run to global scope.
            if !self.global && !self.local && self.global_config_declares_tools(ts) {
                miseprintln!(
                    "{} No tools configured to lock in this project, but global config declares tools. Run {} to lock those.",
                    style("!").yellow(),
                    style("mise lock --global").cyan()
                );
            } else {
                miseprintln!("{} No tools configured to lock", style("!").yellow());
            }
        }

        // Update config files when a specific version is requested that doesn't match
        // the current prefix (e.g., `mise lock tiny@3.0.1` when config has `tiny = "2"`).
        // Never under --bump, which is documented to leave config files untouched.
        if !self.bump {
            use crate::toolset::outdated_info::{
                    .push(tv.clone());
            }
        }
    }

    for (lockfile_path, versions) in candidate_versions_by_lockfile {
        // Only update existing lockfiles (consistent with update_lockfiles)
        if !lockfile_path.exists() {
            continue;
        }

        let _lock = crate::lock_file::LockFile::new(&lockfile_path)
            .with_callback(|l| debug!("waiting for lock on {}", display_path(l)))
            .lock()?;
        let mut lockfile = Lockfile::read(&lockfile_path)
            .unwrap_or_else(|err| handle_lockfile_read_error(err, &lockfile_path));

        let existing_keys;
        let pre_install_keys = if deferred_retry_only {
            existing_keys = lockfile.all_platform_keys();
            &existing_keys
        } else {
            pre_install_platforms
                .get(&lockfile_path)
                .unwrap_or(&empty_keys)
        };
        let target_platforms = determine_target_platforms_from_lockfile(pre_install_keys)?;

        let versions: Vec<_> = versions
            .into_iter()
            .filter(|tv| {
                let needs_auto_lock = if deferred_retry_only {
                    tool_version_needs_deferred_provenance_retry(&lockfile, tv, &target_platforms)
                } else {
                    tool_version_needs_auto_lock(&lockfile, tv, &target_platforms)
                };
                needs_auto_lock.unwrap_or_else(|err| {
                    debug!(
                        "auto-lock candidate check failed for {}@{} in {}: {}",
                        tv.short(),
                        tv.version,
                        display_path(&lockfile_path),
                        err
                    );
                    false
                })
            })
            .collect();
        if versions.is_empty() {
            continue;
        }

        let semaphore = Arc::new(Semaphore::new(jobs));
        let mut jset: JoinSet<LockResolutionResult> = JoinSet::new();

        for tv in &versions {
            let ba = tv.ba().clone();
            let backend = crate::backend::get(&ba);

            for platform in &target_platforms {
                // Expand platform variants from the backend
                let variants = if let Some(ref backend) = backend {
                    backend.platform_variants(platform)
                } else {
                    vec![platform.clone()]
                };

                for variant in variants {
                    let platform_key = variant.to_key();
                    let target = PlatformTarget::new(variant.clone());

                    // Skip complete targets unless a prior provenance-bearing version
                    // means this target still needs authoritative verification.
                    if let Some(ref backend) = backend
                        && let Ok(options) = backend.resolve_lockfile_options(&tv.request, &target)
                        && let Some(tools) = lockfile.tools.get(&ba.short)
                        && !lockfile_target_needs_auto_lock(
                            tools,
                            &tv.version,
                            &platform_key,
                            &options,
                        )
                    {
                        continue;
                    }

#!/usr/bin/env bash

# hk started publishing Packslip manifests in 1.58.1. Earlier releases must
# continue to install through the registry shorthand, using Aqua.
export MISE_EXPERIMENTAL=0
export MISE_MINIMUM_RELEASE_AGE=0
export MISE_REGISTRY_FLOATING=0

# Registry CI must exercise the newly published preferred backend immediately.
MISE_MINIMUM_RELEASE_AGE=90d mise test-tool hk

assert_contains "mise ls-remote hk@1.57" "1.57.0"
assert_contains "mise ls-remote hk 1.57" "1.57.0"
assert_contains "mise ls-remote hk@sub-0.1:1.58.1" "1.57.0"
assert_contains "mise ls-remote hk@prefix:1.57" "1.57.0"
assert "mise latest hk@1.57" "1.57.0"
assert "mise latest hk 1.57" "1.57.0"
assert_not_contains "MISE_BACKENDS_HK=packslip:github.com/jdx/hk mise ls-remote hk@1.57" "1.57"
assert_fail_contains "MISE_DISABLE_BACKENDS=aqua mise latest hk@1.57" "none of its backends"

cat >mise.toml <<'TOML'
[tools]
hk = ["1.57.0", "1.58.1"]

[settings]
lockfile = true
TOML
mise install
assert_contains "mise exec hk@1.57.0 -- hk --version" "hk 1.57.0"
assert_contains "mise exec hk@1.58.1 -- hk --version" "hk 1.58.1"
assert_contains "cat mise.lock" 'backend = "aqua:jdx/hk"'
assert_contains "cat mise.lock" 'backend = "packslip:github.com/jdx/hk"'
assert_contains "MISE_OFFLINE=1 mise --locked exec hk@1.57.0 -- hk --version" "hk 1.57.0"
assert_contains "MISE_OFFLINE=1 mise --locked exec hk@1.58.1 -- hk --version" "hk 1.58.1"
assert_fail_contains "MISE_DISABLE_BACKENDS=aqua mise latest hk@1.57" "none of its backends"

# Aliases can cross the boundary after their version string is resolved.
cat >>mise.toml <<'TOML'
[tool_alias.hk.versions]
old = "1.57.0"
old_prefix = "prefix:1.57"
TOML
assert_contains "mise exec hk@old -- hk --version" "hk 1.57.0"
assert "mise latest hk@old" "1.57.0"
assert_contains "mise ls-remote hk@old" "1.57.0"
assert_contains "mise ls-remote hk@old_prefix" "1.57.0"

# Explicit backends remain explicit; no fallback after a verification error.
assert_fail_contains "mise install --force packslip:github.com/jdx/hk@1.57.0" "no release"

item.formatted_output:
        &self,
        ctx: &InstallContext,
        mut tv: ToolVersion,
        vfox_plugin: bool,
    ) -> Result<(ToolVersion, PendingPin)> {
        let project = self.project()?;
        let raw_opts = tv.request.options();
        let opts = PackslipOptions::new(&raw_opts);
        let pin = pin(&project, &opts)?;
        let require_log = !opts.allow_unlogged();

        // A stamp first, when the settings ask for one: it says this exact
        // manifest is admitted, and points at it. Then the manifest: nothing
        // else is downloaded until it verifies.
        let stamp = match crate::packslip_stamps::fetch(&project, &raw_opts).await? {
            Some(stamps) => Some(
                stamps
                    .stamp(&tv.version)
                    .ok_or_else(|| stamps.refusal(&project, &tv.version))?
                    .clone(),
            ),
            None => None,
        };
        // The vendor stays authoritative for withdrawals and digest pins even
        // when a stamper supplies a mirror URL. What the vendor's list cannot
        // speak to is whether the original release asset is still on GitHub,
        // and a stamp already names the manifest and its digest — so mise asks
        // the signed list here rather than `locate_bundle`, and a deleted asset
        // does not veto a release the vendor never withdrew.
        let (located, vendor_digest) = match &stamp {
            Some(stamp) => {
                debug!(
                    "{}: stamped by {}, manifest at {}",
                    tv.style(),
                    stamp.host,
                    stamp.entry.packslip
                );
                // A stamp says a host reviewed this manifest, and the digest is
                // the whole of what ties the claim to a file. Without one the
                // stamp admits a URL, and any later manifest the vendor signs
                // for this version can stand at it in place of the reviewed
                // one — so refuse rather than call that a review.
                let Some(digest) = stamp.digest.clone() else {
                    bail!(
                        "the stamp for packslip:{project}@{} from {} records no sha256 for {}, so nothing says the manifest is the one that host reviewed",
                        tv.version,
                        stamp.host,
                        stamp.entry.packslip
                    );
                };
                let vendor = self.vendor_entry(&project, &tv, &pin, &opts).await?;
                (
                    Located {
                        headers: headers_for(&stamp.entry.packslip)?,
                        url: stamp.entry.packslip.clone(),
                        digest: Some(digest),
                    },
                    vendor.and_then(|v| v.digest),
                )
            }
            // Without a stamp the located bundle is the vendor's own, so its
            // digest is already the one checked below.
            None => (self.locate_bundle(&project, &tv, &pin, &opts).await?, None),
        };
        let bundle_path = tv.download_path().join(bundle_name(&project));
        file::create_dir_all(tv.download_path())?;
        ctx.pr.set_message("download packslip".into());
        HTTP.download_file_with_headers(
            &located.url,
            &bundle_path,
            &located.headers,
            Some(ctx.pr.as_ref()),
        )
        .await?;
        let pinned: Vec<&String> = located.digest.iter().chain(vendor_digest.iter()).collect();
        if !pinned.is_empty() {
            let (actual, _) = packslip::digest_file(&bundle_path)?;
            for expected in pinned {
                if &actual != expected {
                    bail!(
                        "the packslip at {} is not the one the signed release list points at (sha256 {actual}, list says {expected})",
                        located.url
                    );
                }
            }
        }
        let bundle = file::read_to_string(&bundle_path)?;
        ctx.pr.set_message("verify packslip".into());
        let verified = verify_bundle(&bundle, &pin, require_log, &[])
            .wrap_err_with(|| format!("verifying the packslip of {}", tv.style()))?;
        let payload = packslip::sigstore::peek_statement(&bundle).map_err(|e| eyre!("{e}"))?;
        let statement: Statement = serde_json::from_slice(&payload)?;
        if verified.project != project {
            bail!("the packslip is for {}, not {project}", verified.project);
        }
        if verified.version != tv.version {
            bail!(
                "the packslip says version {}, not {}; the release's tag and its manifest disagree",
                verified.version,
                tv.version
            );
        }
        debug!(
            "{}: packslip signed by {} ({}){}",
            tv.style(),
            verified.key_id,
            verified.scheme,
            verified
                .logged_at
                .as_deref()
                .map(|t| format!(", logged {t}"))
                .unwrap_or_default()
        );
        let before = crate::install_before::resolve_before_date_for_tool(
            &self.ba,
            tv.before_date.or(ctx.before_date),
            raw_opts.minimum_release_age(),
        )?;
        check_verified_age(
            verified.logged_at.as_deref(),
            &verified.published_at,
            before,
        )?;

        // Who signed, against what this machine accepted before, and then
        // against what the project committed to in its lockfile.
        let scheme = verified.scheme.to_string();
        let attested_by = verified.attested_by.to_string();
        // Nothing is recorded until the release is accepted in full, so a
        // refused install leaves no pin behind.
        let observed = Observed {
            scheme: &scheme,
            key_id: &verified.key_id,
            issuer: verified.issuer.as_deref(),
            attested_by: &attested_by,
            provenance: verified.provenance_linked,
            logged: verified.logged_at.is_some(),
        };
        packslip_pins::check(&project, observed)?;
        let signer = format!(
            "{scheme}:{}",
            packslip_pins::signer_of(&scheme, &verified.key_id)
        );
        let platform_key = self.get_platform_key();
        // The signer describes the release, so every platform's lock entry
        // speaks for it, not only this host's.
        for info in tv.lock_platforms.values() {
            if let Some(locked) = &info.signer
                && *locked != signer
            {
                bail!(
                    "mise.lock says {} signed {}, but this release is signed by {signer}; remove the entry from mise.lock to accept the new signer",
                    locked,
                    tv.style()
                );
            }
            if info.attested_by.is_none()
                && info.signer.is_some()
                && verified.attested_by == packslip::Attestor::Repackager
            {
                bail!(
                    "mise.lock says the vendor's own packslip was accepted for {}, but this release is a repackager's; remove the entry from mise.lock to accept that",
                    tv.style()
                );
            }
        }

        // Then the one artifact for this host, by what the manifest says.
        let artifact = select_artifact(
            &statement.predicate.artifacts,
            &HostPlatform::current(),
            opts.variant().as_deref(),
        )?
        .clone();
        if vfox_plugin {
            crate::plugins::packslip::validate_artifact(&artifact)?;
        }
        let mut commands = BTreeMap::new();
        if let Some(req) = &artifact.requires {
            for bin in &req.bin {
                // Spawnable, not merely present: the probe below runs the
                // path with `--version`, so a shebang-only script or a `.ps1`
                // would be chosen and then fail to start.
                if let Some(path) = ctx.ts.which_bin_spawnable(&ctx.config, &bin.name).await {
                    commands.insert(bin.name.clone(), path);
                }
            }
        }
        crate::packslip_requirements::check(&artifact, &commands)
            .await
            .enforce(raw_opts.get("ignore_requirements") == Some("true"))?;
        let Some(url) = artifact.url.clone() else {
            bail!("the packslip gives no download URL for {}", artifact.name);
        };
        if !file::is_plain_file_name(&artifact.name) {
            bail!(
                "the packslip names an artifact {:?}, which is not a plain file name",
                artifact.name
            );
        }
        let file_path = tv.download_path().join(&artifact.name);
        ctx.pr.next_operation();
        ctx.pr.set_message(format!("download {}", artifact.name));
        HTTP.download_file_with_headers(
            &url,
            &file_path,
            &headers_for(&url)?,
            Some(ctx.pr.as_ref()),
        )
        .await?;

        // The signed digest and size first, then what the lockfile remembers:
        // a lock entry written from an earlier packslip keeps its checksum and
        // is compared, so a newly signed manifest cannot quietly replace what
        // the project committed to. A fresh entry records the signed sha256.
        ctx.pr.next_operation();
        ctx.pr.set_message(format!("verify {}", artifact.name));
        verify_bundle(&bundle, &pin, require_log, &[&file_path])
            .wrap_err_with(|| format!("verifying {} against its packslip", artifact.name))?;
        {
            let info = tv.lock_platforms.entry(platform_key).or_default();
            info.url = Some(url);
            if info.checksum.is_none()
                && let Some(sha256) = statement.digest_of(&artifact.name)
            {
                info.checksum = Some(format!("sha256:{sha256}"));
            }
            info.signer = Some(signer);
            // Set for a repackager's document and cleared for the vendor's,
            // so the lockfile ratchets up the way the pin does.
            info.attested_by = (verified.attested_by == packslip::Attestor::Repackager)
                .then(|| "repackager".to_string());
        }
        self.verify_checksum(ctx, &mut tv, &file_path)?;

        // Unpack as the manifest describes the file, not as its name suggests.
        ctx.pr.next_operation();
        let mut install_opts = tv.request.options();
        if let Some(format) = &artifact.format {
            install_opts
                .insert_option("format".into(), toml::Value::String(format.clone()))
                .map_err(|e| eyre!(e))?;
        }
        // A bare executable, compressed or not, lands at the path its bin
        // entry names: the artifact's own name minus any compression suffix.
        if artifact.format.as_deref().is_some_and(is_bare_format)
            && let Some(bin) = artifact.bin.first()
        {
            install_opts
                .insert_option("bin".into(), toml::Value::String(bin.path.clone()))
                .map_err(|e| eyre!(e))?;
        }
        // The statement names every executable by path, so nothing here may
        // rename one: a tidied platform suffix would put the file somewhere the
        // statement does not point, and `link_bins` would not find it.
        if vfox_plugin {
            crate::plugins::packslip::validate_archive(&file_path)?;
        }
        install_artifact(
            &tv,
            &file_path,
            &install_opts,
            ArchiveLayout::Declared,
            Some(ctx.pr.as_ref()),
        )?;
        if vfox_plugin {
            crate::plugins::packslip::validate_layout(&tv.install_path())?;
        }
        Self::link_bins(&tv, &artifact)?;
        file::write(
            tv.install_path().join(STATEMENT_FILE),
            serde_json::to_vec_pretty(&statement)?,
        )?;
        // Completions and CLI specs the vendor keeps outside the artifact.
        if !vfox_plugin {
            crate::packslip::fetch_files(&tv, &statement, Some(&artifact), ctx.pr.as_ref()).await?;
        }
        Ok((
            tv,
            PendingPin {
                project,
                scheme: observed.scheme.to_owned(),
                key_id: observed.key_id.to_owned(),
                issuer: observed.issuer.map(str::to_owned),
                attested_by: observed.attested_by.to_owned(),
                provenance: observed.provenance,
                        .lock()?;
                    let original_content = read_optional_file(&lockfile_path)?;
                    let mut lockfile = Lockfile::read(&lockfile_path)?;
                    if self.json {
                        all_changes.extend(self.compute_version_changes(
                            &lockfile,
                            &tools,
                            &lockfile_path,
                        ));
                    }
                    let pruned_tools = self.prune_stale_entries_if_needed(
                        &mut lockfile,
                        configured_selectors.as_ref(),
                    );
                    let format_changed = if self.upgrade {
                        if lockfile.tools().is_empty() {
                            self.prepare_lockfile_format(&lockfile_path, &mut lockfile)
                        } else {
                            bail!(
                                "cannot upgrade {} because no configured tools were resolved",
                                display_path(&lockfile_path)
                            );
                        }
                    } else {
                        self.report_lockfile_format(&lockfile_path, &lockfile, false)?;
                        false
                    };
                    if format_changed || !pruned_tools.is_empty() {
                        if self.upgrade {
                            staged_upgrade_writes.push(StagedUpgradeWrite {
                                path: lockfile_path.clone(),
                                original_content,
                                lockfile,
                                summary: None,
                                format_changed,
                                stale_tools: pruned_tools.clone(),
                                stale_versions: BTreeMap::new(),
                            });
                        } else {
                            lockfile.write(&lockfile_path)?;
                        }
                        if !self.upgrade {
                            self.show_stale_prune_message(&lockfile_path, &pruned_tools, false)?;
                        }
                        has_lock_targets = true;
                    }
                }
                continue;
            }
            has_lock_targets = true;

            let target_platforms = self.determine_target_platforms(&lockfile_path)?;

            if !self.json {
                miseprintln!(
                    "{} Targeting {} platform(s) for {}: {}",
                    style("→").cyan(),
                    target_platforms.len(),
                    style(display_path(&lockfile_path)).cyan(),
                    target_platforms
                        .iter()
                        .map(|p| p.to_key())
                        .collect::<Vec<_>>()
                        .join(", ")
                );

                miseprintln!(
                    "{} Processing {} tool(s): {}",
                    style("→").cyan(),
                    tools.len(),
                    tools
                        .iter()
                        .map(|(ba, tv)| format!("{}@{}", ba.short, tv.version))
                        .collect::<Vec<_>>()
                        .join(", ")
                );
            }

            if self.dry_run {
                self.show_dry_run(&tools, &target_platforms)?;
                let lockfile = Lockfile::read(&lockfile_path)?;
                self.report_lockfile_format(&lockfile_path, &lockfile, true)?;
                if self.json {
                    all_changes.extend(self.compute_version_changes(
                        &lockfile,
                        &tools,
                        &lockfile_path,
                    ));
                }
                if self.is_unfiltered_lock_run() {
                    let stale_tools =
                        self.stale_entries_if_pruned(&lockfile, configured_selectors.as_ref());
                    self.show_stale_prune_message(&lockfile_path, &stale_tools, true)?;
                }
                let stale_versions = self.stale_versions_if_pruned(&lockfile, &tools);
                self.show_stale_version_prune_message(&lockfile_path, &stale_versions, true)?;
                continue;
            }

            // Process tools and update lockfile
            let _lock = crate::lock_file::LockFile::new(&lockfile_path)
                .with_callback(|l| debug!("waiting for lock on {}", display_path(l)))
                .lock()?;
            let original_content = read_optional_file(&lockfile_path)?;
            let mut lockfile = Lockfile::read(&lockfile_path)?;
            if !self.upgrade {
                self.report_lockfile_format(&lockfile_path, &lockfile, false)?;
            }
            if self.json {
                all_changes.extend(self.compute_version_changes(&lockfile, &tools, &lockfile_path));
            }
            let stale_tools =
                self.prune_stale_entries_if_needed(&mut lockfile, configured_selectors.as_ref());
            if !self.upgrade {
                self.show_stale_prune_message(&lockfile_path, &stale_tools, false)?;
            }

            // Compute stale versions BEFORE process_tools so provenance checks can
            // compare against old version entries. Actual pruning happens after.
            let stale_versions = self.stale_versions_if_pruned(&lockfile, &tools);

            let (results, resolution_errors) = self
                .process_tools(&settings, &tools, &target_platforms, &mut lockfile)
                .await?;
            let resolution_succeeded = resolution_errors.is_empty();
            all_resolution_errors.extend(resolution_errors);

            let platform_regressions =
                self.platform_regression_errors(&lockfile, &stale_versions, &results);
            if !platform_regressions.is_empty() {
                all_platform_regressions.extend(platform_regressions);
                continue;
            }

            let format_changed =
                self.upgrade && lockfile.lockfile_version() == 0 && resolution_succeeded;
            if format_changed {
                self.prepare_lockfile_format(&lockfile_path, &mut lockfile);
                if !self.bind_requests(&mut lockfile, &tools, &target_platforms) {
                    bail!(
                        "cannot upgrade {} because not every request binding was resolved",
                        display_path(&lockfile_path)
                    );
                }
            } else {
                self.bind_requests(&mut lockfile, &tools, &target_platforms);
            }

            // Prune stale versions AFTER provenance checks complete
            self.prune_stale_versions(&mut lockfile, &tools);
            if !self.upgrade {
                self.show_stale_version_prune_message(&lockfile_path, &stale_versions, false)?;
            }

            let successful = results
                .iter()
                .filter(|result| matches!(result.status, LockTaskStatus::Updated))
                .count();
            let skipped = results.len() - successful;
            if self.upgrade {
                staged_upgrade_writes.push(StagedUpgradeWrite {
                    path: lockfile_path.clone(),
                    original_content,
                    lockfile,
                    summary: Some((successful, skipped)),
                    format_changed,
                    stale_tools,
                    stale_versions,
                });
            } else {
                // Normal lock runs preserve successful updates even if another
                // target reports a non-regressing resolution error.
                lockfile.write(&lockfile_path)?;
            }

            // Print summaries for normal writes now. Upgrade summaries are
            // deferred with their writes until every target succeeds.
            if !self.json && !self.upgrade {
                miseprintln!(
                    "{} Updated {} platform entries ({} skipped)",
                    style("✓").green(),
                    successful,
                    skipped
                );
                miseprintln!(
                    "{} Lockfile written to {}",
                    style("✓").green(),
                    style(display_path(&lockfile_path)).cyan()
                );
            }
        }

        if !has_lock_targets && !self.json {
            // --local asks for mise.local.lock specifically, and there is no global
            // equivalent, so don't redirect that run to global scope.
            if !self.global && !self.local && self.global_config_declares_tools(ts) {
                miseprintln!(
                    "{} No tools configured to lock in this project, but global config declares tools. Run {} to lock those.",
                    style("!").yellow(),
                    style("mise lock --global").cyan()
                );
            } else {
                miseprintln!("{} No tools configured to lock", style("!").yellow());
            }
        }

        // Update config files when a specific version is requested that doesn't match
        // the current prefix (e.g., `mise lock tiny@3.0.1` when config has `tiny = "2"`).
        // Never under --bump, which is documented to leave config files untouched.
        if !self.bump {
            use crate::toolset::outdated_info::{
                    .push(tv.clone());
            }
        }
    }

    for (lockfile_path, versions) in candidate_versions_by_lockfile {
        // Only update existing lockfiles (consistent with update_lockfiles)
        if !lockfile_path.exists() {
            continue;
        }

        let _lock = crate::lock_file::LockFile::new(&lockfile_path)
            .with_callback(|l| debug!("waiting for lock on {}", display_path(l)))
            .lock()?;
        let mut lockfile = Lockfile::read(&lockfile_path)
            .unwrap_or_else(|err| handle_lockfile_read_error(err, &lockfile_path));

        let existing_keys;
        let pre_install_keys = if deferred_retry_only {
            existing_keys = lockfile.all_platform_keys();
            &existing_keys
        } else {
            pre_install_platforms
                .get(&lockfile_path)
                .unwrap_or(&empty_keys)
        };
        let target_platforms = determine_target_platforms_from_lockfile(pre_install_keys)?;

        let versions: Vec<_> = versions
            .into_iter()
            .filter(|tv| {
                let needs_auto_lock = if deferred_retry_only {
                    tool_version_needs_deferred_provenance_retry(&lockfile, tv, &target_platforms)
                } else {
                    tool_version_needs_auto_lock(&lockfile, tv, &target_platforms)
                };
                needs_auto_lock.unwrap_or_else(|err| {
                    debug!(
                        "auto-lock candidate check failed for {}@{} in {}: {}",
                        tv.short(),
                        tv.version,
                        display_path(&lockfile_path),
                        err
                    );
                    false
                })
            })
            .collect();
        if versions.is_empty() {
            continue;
        }

        let semaphore = Arc::new(Semaphore::new(jobs));
        let mut jset: JoinSet<LockResolutionResult> = JoinSet::new();

        for tv in &versions {
            let ba = tv.ba().clone();
            let backend = crate::backend::get(&ba);

            for platform in &target_platforms {
                // Expand platform variants from the backend
                let variants = if let Some(ref backend) = backend {
                    backend.platform_variants(platform)
                } else {
                    vec![platform.clone()]
                };

                for variant in variants {
                    let platform_key = variant.to_key();
                    let target = PlatformTarget::new(variant.clone());

                    // Skip complete targets unless a prior provenance-bearing version
                    // means this target still needs authoritative verification.
                    if let Some(ref backend) = backend
                        && let Ok(options) = backend.resolve_lockfile_options(&tv.request, &target)
                        && let Some(tools) = lockfile.tools.get(&ba.short)
                        && !lockfile_target_needs_auto_lock(
                            tools,
                            &tv.version,
                            &platform_key,
                            &options,
                        )
                    {
                        continue;
                    }

#!/usr/bin/env bash

# hk started publishing Packslip manifests in 1.58.1. Earlier releases must
# continue to install through the registry shorthand, using Aqua.
export MISE_EXPERIMENTAL=0
export MISE_MINIMUM_RELEASE_AGE=0
export MISE_REGISTRY_FLOATING=0

# Registry CI must exercise the newly published preferred backend immediately.
MISE_MINIMUM_RELEASE_AGE=90d mise test-tool hk

assert_contains "mise ls-remote hk@1.57" "1.57.0"
assert_contains "mise ls-remote hk 1.57" "1.57.0"
assert_contains "mise ls-remote hk@sub-0.1:1.58.1" "1.57.0"
assert_contains "mise ls-remote hk@prefix:1.57" "1.57.0"
assert "mise latest hk@1.57" "1.57.0"
assert "mise latest hk 1.57" "1.57.0"
assert_not_contains "MISE_BACKENDS_HK=packslip:github.com/jdx/hk mise ls-remote hk@1.57" "1.57"
assert_fail_contains "MISE_DISABLE_BACKENDS=aqua mise latest hk@1.57" "none of its backends"

cat >mise.toml <<'TOML'
[tools]
hk = ["1.57.0", "1.58.1"]

[settings]
lockfile = true
TOML
mise install
assert_contains "mise exec hk@1.57.0 -- hk --version" "hk 1.57.0"
assert_contains "mise exec hk@1.58.1 -- hk --version" "hk 1.58.1"
assert_contains "cat mise.lock" 'backend = "aqua:jdx/hk"'
assert_contains "cat mise.lock" 'backend = "packslip:github.com/jdx/hk"'
assert_contains "MISE_OFFLINE=1 mise --locked exec hk@1.57.0 -- hk --version" "hk 1.57.0"
assert_contains "MISE_OFFLINE=1 mise --locked exec hk@1.58.1 -- hk --version" "hk 1.58.1"
assert_fail_contains "MISE_DISABLE_BACKENDS=aqua mise latest hk@1.57" "none of its backends"

# Aliases can cross the boundary after their version string is resolved.
cat >>mise.toml <<'TOML'
[tool_alias.hk.versions]
old = "1.57.0"
old_prefix = "prefix:1.57"
TOML
assert_contains "mise exec hk@old -- hk --version" "hk 1.57.0"
assert "mise latest hk@old" "1.57.0"
assert_contains "mise ls-remote hk@old" "1.57.0"
assert_contains "mise ls-remote hk@old_prefix" "1.57.0"

# Explicit backends remain explicit; no fallback after a verification error.
assert_fail_contains "mise install --force packslip:github.com/jdx/hk@1.57.0" "no release"

output.text:
        &self,
        ctx: &InstallContext,
        mut tv: ToolVersion,
        vfox_plugin: bool,
    ) -> Result<(ToolVersion, PendingPin)> {
        let project = self.project()?;
        let raw_opts = tv.request.options();
        let opts = PackslipOptions::new(&raw_opts);
        let pin = pin(&project, &opts)?;
        let require_log = !opts.allow_unlogged();

        // A stamp first, when the settings ask for one: it says this exact
        // manifest is admitted, and points at it. Then the manifest: nothing
        // else is downloaded until it verifies.
        let stamp = match crate::packslip_stamps::fetch(&project, &raw_opts).await? {
            Some(stamps) => Some(
                stamps
                    .stamp(&tv.version)
                    .ok_or_else(|| stamps.refusal(&project, &tv.version))?
                    .clone(),
            ),
            None => None,
        };
        // The vendor stays authoritative for withdrawals and digest pins even
        // when a stamper supplies a mirror URL. What the vendor's list cannot
        // speak to is whether the original release asset is still on GitHub,
        // and a stamp already names the manifest and its digest — so mise asks
        // the signed list here rather than `locate_bundle`, and a deleted asset
        // does not veto a release the vendor never withdrew.
        let (located, vendor_digest) = match &stamp {
            Some(stamp) => {
                debug!(
                    "{}: stamped by {}, manifest at {}",
                    tv.style(),
                    stamp.host,
                    stamp.entry.packslip
                );
                // A stamp says a host reviewed this manifest, and the digest is
                // the whole of what ties the claim to a file. Without one the
                // stamp admits a URL, and any later manifest the vendor signs
                // for this version can stand at it in place of the reviewed
                // one — so refuse rather than call that a review.
